from typing import Sequence

class StepScheduler:
    def __init__(self, components: Sequence[object]):
        self.components = components
        self.time = 0.0

    def run(self, stop_time: float, step: float) -> float:
        if step <= 0:
            raise ValueError('step must be positive')

        while self.time < stop_time:
            target = min(self.time + step, stop_time)
            for component in self.components:
                component.set_time(target)
            for component in self.components:
                component.advance()
            for component in self.components:
                component.wait_until(target)
            self.time = target

        return self.time
